const blocked = blockedCountries();
const found = ($('Agregace nálezů').first().json.data || []).filter(l => l && l.id);
const existing = clean($input.all());
const ids = new Set(existing.map(e => String(e.id)));
const doms = new Set(existing.map(e => domainOfUrl(e.website)).filter(Boolean));
const now = DateTime.now().toISO();
const COLS = ["id", "created_at", "market", "lang", "country", "tz", "legal_regime", "name", "category", "primary_type", "city", "address", "phone", "email", "whatsapp", "whatsapp_opt_in", "website", "has_website", "maps_url", "rating", "rating_count", "industry", "branch", "score", "reasons", "reasons_cs", "preview_url", "compare_png_url", "og_png_url", "status", "batch_id", "notified_at", "approved_at", "custom_intro", "custom_subject", "subject_variant", "sent_1_at", "sent_2_at", "sent_3_at", "thread_id", "last_message_id", "last_reply_at", "last_channel", "auto_reply_count", "manual_takeover", "price_quoted", "notes", "next_action"];
const seen = new Set();
const out = [];
let dupId = 0, dupDom = 0, blk = 0;
for (const l of found) {
  const id = String(l.id);
  const country = String(l.country || '').toUpperCase();
  const dom = domainOfUrl(l.website);
  if (blocked.has(country)) { blk++; continue; }
  if (ids.has(id) || seen.has(id)) { dupId++; continue; }
  if (dom && (doms.has(dom) || seen.has('d:' + dom))) { dupDom++; continue; }
  seen.add(id); if (dom) seen.add('d:' + dom);
  const row = {}; for (const c of COLS) row[c] = '';
  Object.assign(row, {
    id, created_at: now, market: l.market || (l.lang === 'cs' ? 'cz' : 'en'), lang: l.lang || 'en', country,
    tz: l.tz || '', legal_regime: l.legal_regime || '', name: l.name, category: l.category || '', primary_type: l.primary_type || '',
    city: l.city || '', address: l.address || '', phone: l.phone || l.phone_intl || '', email: '', website: l.website || '',
    has_website: !!(l.has_website || l.website), maps_url: l.maps_url || '', rating: l.rating ?? '', rating_count: l.rating_count ?? '',
    status: 'new', auto_reply_count: 0, manual_takeover: false,
  });
  out.push({ json: row });
}
console.log(`nalezeno ${found.length}, nových ${out.length}, duplicitní ID ${dupId}, duplicitní doména ${dupDom}, blokované ${blk}`);
if (!out.length) return [{ json: { _none: true, found: found.length, dupId, dupDom, blk } }];
return out;
